    def matrix_mult(A, B, mod):
        """Multiply two 2x2 matrices modulo mod"""
        result = [[0, 0], [0, 0]]
        for i in range(2):
            for j in range(2):
                for k in range(2):
                    result[i][j] = (result[i][j] + A[i][k] * B[k][j]) % mod
        return result

    def matrix_pow(M, n, mod):
        """Compute M^n mod 'mod' using fast exponentiation"""
        if n == 1:
            return M

        # Start with identity matrix
        result = [[1, 0], [0, 1]]
        base = [row[:] for row in M]  # Copy M

        while n > 0:
            if n % 2 == 1:
                result = matrix_mult(result, base, mod)
            base = matrix_mult(base, base, mod)
            n //= 2

        return result

    M = inputs.get('M', [[21, 13], [20, 25]])
    exponent = inputs.get('exponent', 26)
    mod = inputs.get('mod', 135804)

    result_matrix = matrix_pow(M, exponent, mod)

    # Sum all entries
    total = sum(result_matrix[i][j] for i in range(2) for j in range(2))

    return float(total % mod)

